from collections import Counter

def check_schedule(tasks, cooldown, duration):
    original = list(tasks)
    slots = schedule(tasks, cooldown)
    assert isinstance(slots, list), "return a list, not printed output"
    assert tasks == original, "do not mutate the input tasks"
    assert Counter(x for x in slots if x is not None) == Counter(tasks), "execute each supplied task exactly once"
    previous = {}
    for time, label in enumerate(slots):
        if label is not None:
            assert label not in previous or time - previous[label] >= cooldown + 1, "a repeated task ran too early"
            previous[label] = time
    assert len(slots) == duration, "the schedule contains unnecessary idle time"

for tasks, cooldown, duration in [
    ([], 4, 0),
    (list("AAA"), 2, 7),
    (list("AABB"), 2, 5),
    (list("ABCABC"), 2, 6),
    (list("AAAAABC"), 2, 13),
    (list("AAABBC"), 2, 7),
    (list("BAA"), 0, 3),
    (list("AB"), 12, 2),
]:
    check_schedule(tasks, cooldown, duration)
for bad in [-1, 1.5, True]:
    try:
        schedule([], bad)
    except ValueError:
        pass
    else:
        raise AssertionError("reject invalid cooldown")
for bad_label in ["a", "AA", 4, None]:
    try:
        schedule([bad_label], 1)
    except ValueError:
        pass
    else:
        raise AssertionError("reject a label outside A-Z")

